class Solution:
    def minTimeForRounds(self, roundTime: List[int], totalRounds: int) -> int:
        lo, hi = 1, min(roundTime) * totalRounds
        while lo < hi:
            mid = (lo + hi) // 2
            if sum(mid // r for r in roundTime) >= totalRounds:
                hi = mid
            else:
                lo = mid + 1
        return lo

