class Solution {
    public long minTimeForRounds(int[] roundTime, int totalRounds) {
        int fastest = Integer.MAX_VALUE;
        for (int r : roundTime) fastest = Math.min(fastest, r);
        long lo = 1, hi = (long) fastest * totalRounds;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            long done = 0;
            for (int r : roundTime) { done += mid / r; if (done >= totalRounds) break; }
            if (done >= totalRounds) hi = mid; else lo = mid + 1;
        }
        return lo;
    }
}

