long long minTimeForRounds(int* roundTime, int roundTimeSize, int totalRounds) {
    int fastest = roundTime[0];
    for (int i = 1; i < roundTimeSize; i++) if (roundTime[i] < fastest) fastest = roundTime[i];
    long long lo = 1, hi = (long long) fastest * totalRounds;
    while (lo < hi) {
        long long mid = lo + (hi - lo) / 2;
        long long done = 0;
        for (int i = 0; i < roundTimeSize && done < totalRounds; i++) done += mid / roundTime[i];
        if (done >= totalRounds) hi = mid; else lo = mid + 1;
    }
    return lo;
}
